with parsed as (select id, customer_id, created_at, coupon_codes, items, array_max(transform(items, x -> x.price)) as max_item_price, coalesce(attributes['utm_source'], 'unknown') as utm_source_or_default, coalesce(attributes['device'], 'none') as device_or_default, ship_to.zip as ship_zip from carts where created_at < '2024-02-01') select *, row_number() over (partition by customer_id order by created_at desc, id) as row_seq, sum(max_item_price) over (partition by customer_id order by max_item_price, id rows between unbounded preceding and current row) as running_max_item_price, min(max_item_price) over (partition by customer_id) as customer_id_min_max_item_price, avg(max_item_price) over (partition by customer_id order by created_at, id rows between 3 preceding and current row) as max_item_price_avg_3 from parsed;
